        ['title','acceptance'].filter(key=>previous.get(id)[key]!==previous.get(id).sourceValues[key])})),
    removedTasks:[...previous].filter(([key,row])=>!next.has(key)&&!row.retired).map(([id,row])=>({id,title:row.title})),
