  for(const row of later) {
    if(map.has(row.id))ensure(stable(map.get(row.id))===stable(row),
      'Restored '+label+' conflicts with retained original '+row.id,'HISTORY_CONFLICT');
    else map.set(row.id,copy(row));
  }
